import zipfile
import xml.etree.ElementTree as ET

def get_sheet_names(xlsx_path):
    with zipfile.ZipFile(xlsx_path, 'r') as z:
        # Read xl/workbook.xml to get sheet names and ids
        wb_xml = z.read('xl/workbook.xml')
        root = ET.fromstring(wb_xml)

        # namespaces
        ns = {'workbook': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

        sheets = []
        for elem in root.iter():
            if elem.tag.endswith('sheet'):
                name = elem.attrib.get('name')
                sheet_id = elem.attrib.get('sheetId')
                r_id = elem.attrib.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
                sheets.append({'name': name, 'sheet_id': sheet_id, 'r_id': r_id})
        return sheets

files = [
    'LBO_Model_FY2025_Interest_Coverage_Reference.xlsx',
    '4. Model/LBO Model/Project Vanguard - 11.20.2025 - LBO Model_v1.xlsx'
]

